import React, { useEffect, useState } from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import {
    Button as HeroButton,
    Dropdown,
    Kbd,
    Label,
    Popover,
    PopoverContent,
} from "@heroui/react"
import {
    BellIcon,
    ChecksIcon,
    CircleIcon,
    MagnifyingGlassIcon,
    ShoppingCartIcon,
    SidebarSimpleIcon,
    UserIcon,
} from "@phosphor-icons/react"
import { NavbarLanguageMenu } from "./NavbarLanguageMenu"
import { NavbarThemeSwitch } from "./NavbarThemeSwitch"
import type { NavbarLanguageOption } from "./types"
import { Logo } from "@sb-components/atoms/display/Logo/Logo"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Badge } from "@sb-components/atoms/display/Badge/Badge"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { UserCell } from "@sb-components/composites/lists/UserCell/UserCell"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Button, type IconComponent } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { InputButtonLike } from "@sb-components/composites/buttons/InputButtonLike/InputButtonLike"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { ListRow } from "@sb-components/composites/lists/List/List"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import { HideAbove } from "@sb-components/frames/HideAbove/HideAbove"
import { ScrollArea } from "@sb-components/frames/ScrollArea/ScrollArea"
import { ShowFrom } from "@sb-components/frames/ShowFrom/ShowFrom"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `Navbar` ΓÇö the sticky top app bar. Two structural leaves: the desktop row
 * (route pills + inline language/theme) and the mobile collapsed row (icon bar
 * + drawer trigger) are different compositions. Signed-in vs guest, empty vs
 * busy badges, and drawer open vs closed are data, so they are states inside
 * the matching leaf. Both leaves render the same component (the `@app-md:`
 * rules live in its className), so the mobile leaf pins a narrow
 * `renderClassName` frame to force the collapsed row into view.
 */

/** One top-level desktop/mobile route entry. */
export interface NavLinkItem {
    /** Stable id ΓÇö also the value reported to the desktop pill group. */
    id: string
    /** Visible label, already localized by the caller. */
    label: string
    /** Whether this entry matches the current route. */
    isActive?: boolean
    /** Fired when the entry is picked (desktop pill or mobile drawer row). */
    onPress: () => void
}

export type { NavbarLanguageOption }

/** One row in the notification popover's list. */
export interface NavbarNotificationItem {
    /** Stable id. */
    id: string
    /** Primary line, already resolved/translated by the caller. */
    title: string
    /** Optional secondary line. */
    subtitle?: string
    /** Already-formatted relative time (e.g. "3 hours ago") ΓÇö locale math is app wiring. */
    timeLabel: string
    /** `false` renders the unread dot leading the row. */
    isRead: boolean
}

/** Notification bell data + the callbacks its popover fires. */
export interface NavbarNotificationsData {
    /** Drives the bell's count badge; `0` hides it. */
    unreadCount: number
    /** Most-recent page, newest first. */
    items: Array<NavbarNotificationItem>
    /** `true` while the FIRST page is loading (no cache yet). */
    isLoading: boolean
    /** Already-translated error message; `null`/absent ΓåÆ no error branch. */
    error?: string | null
    /** Fired when a row is pressed (mark-read + navigate is the caller's job). */
    onItemPress: (item: NavbarNotificationItem) => void
    /** Fired by the header's bulk action. */
    onMarkAllRead: () => void
    /** Fired by the footer's deep-link action. */
    onSeeAll: () => void
    /** Fired by the error branch's retry button. */
    onRetry: () => void
}

/** The signed-in viewer, as far as the account menu's header row needs to know. */
export interface NavbarAccountUser {
    /** Drives the avatar fallback + the header row's primary line. */
    username: string
    /** Shown as the header row's secondary `@handle` line. */
    email?: string
    /** Uploaded avatar URL; `Avatar`'s own fallback chain covers the rest. */
    avatarUrl?: string | null
}

/** One row of the account dropdown's action list ΓÇö covers BOTH the guest rows
 * (sign in / sign up) and the authed rows (dashboard / profile / sign out); the
 * caller decides which set to hand in via {@link NavbarAccountData.isAuthed}. */
export interface NavbarAccountMenuItem {
    /** Stable id. */
    id: string
    /** Visible label, already localized. */
    label: string
    /** Leading glyph, atom-scale (`size-5`) as this block owns the icon column. */
    icon?: IconComponent
    /** `true` ΓåÆ renders in the destructive tone (e.g. "Sign out"). */
    isDanger?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Account menu data + the one state flag its header/list branch on. */
export interface NavbarAccountData {
    /** `true` ΓåÆ header shows {@link NavbarAccountData.user}; `false` ΓåÆ the guest prompt. */
    isAuthed: boolean
    /** Present only when {@link NavbarAccountData.isAuthed}. */
    user?: NavbarAccountUser
    /** `true` while the shared "who am I" query has not resolved yet. */
    isLoading: boolean
    /** The action rows below the header (see {@link NavbarAccountMenuItem}). */
    menuItems: Array<NavbarAccountMenuItem>
}

/** Props for {@link Navbar}. */
export interface NavbarProps {
    /** Fired when the brand mark is pressed ΓÇö routing "home" is the caller's call. */
    onLogoPress: () => void
    /** Route entries ΓÇö the ONE source both the desktop pills and the mobile drawer read. */
    navItems: Array<NavLinkItem>

    /** Placeholder text for the desktop search field; doubles as the mobile icon's aria-label. */
    searchPlaceholder: string
    /** Already-formatted shortcut hint (e.g. `"Ctrl K"`, `"ΓîÿK"`) ΓÇö OS detection is app wiring. */
    shortcutLabel: string
    /** Fired when the search trigger (field or icon) is pressed, or Ctrl/Cmd+K is hit. */
    onSearchPress: () => void

    /** Selectable locales. */
    languages: Array<NavbarLanguageOption>
    /** Currently active locale ΓÇö must match one entry's `code`. */
    activeLocale: string
    /** Fired with the newly picked locale code. */
    onLocaleChange: (code: string) => void

    /** Dark-mode on/off (controlled). */
    isDarkMode: boolean
    /** Fired with the new on/off state. */
    onThemeToggle: (isDark: boolean) => void

    /** Items currently in the cart; `0` hides the count badge. */
    cartCount: number
    /** Fired when the cart icon is pressed. */
    onCartPress: () => void

    /** Notification bell data + callbacks. */
    notifications: NavbarNotificationsData
    /** Account menu data + callbacks. */
    account: NavbarAccountData

    /** Whether the mobile navigation drawer is open. Controlled by the caller. */
    isMobileDrawerOpen: boolean
    /** Fired on backdrop click / Escape / the close button / a row navigating away. */
    onMobileDrawerOpenChange: (isOpen: boolean) => void
}

interface ShortcutHintProps {
    shortcutLabel: string
}
const ShortcutHint = ({ shortcutLabel }: ShortcutHintProps) => (
    <Kbd><Kbd.Content>{shortcutLabel}</Kbd.Content></Kbd>
)

/**
 * The sticky top app bar. See the file header for the full reuse ledger and the
 * judgement calls this port makes.
 *
 * @param props - {@link NavbarProps}
 */
const Navbar = ({
    onLogoPress,
    navItems,
    searchPlaceholder,
    shortcutLabel,
    onSearchPress,
    languages,
    activeLocale,
    onLocaleChange,
    isDarkMode,
    onThemeToggle,
    cartCount,
    onCartPress,
    notifications,
    account,
    isMobileDrawerOpen,
    onMobileDrawerOpenChange,
}: NavbarProps) => {
    const [isNotificationsOpen, setNotificationsOpen] = useState(false)
    const [isAccountOpen, setAccountOpen] = useState(false)

    // Ctrl/Cmd+K ΓÇö carried over from the real component (see file header): it only
    // ever calls a prop this block already owns, so it is not new app wiring.
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            const isK = event.key?.toLowerCase() === "k"
            if (!isK || !(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            onSearchPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [onSearchPress])

    const activeNavId = navItems.find((item) => item.isActive)?.id ?? ""

    const notificationSkeletonRows = [0, 1, 2].map((row) => (
        <ListRow key={row} title="" isSkeleton />
    ))

    const notificationRows = notifications.items.map((item, index) => (
        <ListRow
            key={item.id}
            leading={!item.isRead ? (
                ({ isSkeleton }: SkeletonProps) =>
                    isSkeleton ? null : <CircleIcon weight="fill" aria-hidden focusable="false" className="size-2 text-accent-soft-foreground" />
            ) : undefined}
            title={item.title}
            subtitle={item.subtitle}
            meta={() => <Typography size="xs" color="muted" text={item.timeLabel} />}
            onPress={() => notifications.onItemPress(item)}
            divider={index < notifications.items.length - 1}
        />
    ))

    const accountMenuHeader = (
        <AsyncContent
            isLoading={account.isLoading}
            skeleton={() => <UserCell username="" isSkeleton />}
            content={() => (account.isAuthed && account.user ? (
                <UserCell
                    username={account.user.username}
                    avatar={account.user.avatarUrl}
                    handle={account.user.email}
                />
            ) : (
                <StackH
                    gap={3}
                    principle="icon-text"
                    explain="Avatar beside its guest prompt ΓÇö not name-handle, because this pairs a glyph with instructional text rather than a name/handle identity."
                    items={[
                        () => <Avatar icon={UserIcon} fallback="icon" />,
                        () => <Typography size="sm" color="muted" text="Sign in to save your learning progress" />,
                    ]}
                />
            ))}
        />
    )

    const mobileNavRows = navItems.map((item) => (
        <Button
            key={item.id}
            variant={item.isActive ? "secondary" : "ghost"}
            align="start"
            label={item.label}
            onPress={() => {
                item.onPress()
                onMobileDrawerOpenChange(false)
            }}
        />
    ))

    return (
        <nav className="sticky top-0 z-50 border-b border-default bg-surface">
            {/* primary row ΓÇö fixed 4rem tall, matching the real bar's height contract */}
            <div className="h-16 min-h-16">
                <StackH
                    gap={6}
                    principle="block-boundary"
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    justify="between"
                    padding={{ x: 4 }}
                    items={[
                        () => (
                            <StackH
                                gap={6}
                                principle="flex-action"
                                explain="Groups brand mark and desktop route pills on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <span
                                            role="button"
                                            tabIndex={0}
                                            aria-label="StarCi Academy"
                                            onClick={onLogoPress}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter" || event.key === " ") onLogoPress()
                                            }}
                                            className="inline-flex cursor-pointer"
                                        >
                                            <Logo />
                                        </span>
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <ButtonRadioGroup
                                                    items={navItems.map((item) => ({
                                                        value: item.id,
                                                        content: <Typography size="sm" text={item.label} />,
                                                    }))}
                                                    value={activeNavId}
                                                    onChange={(id) => navItems.find((item) => item.id === id)?.onPress()}
                                                    ariaLabel="Main navigation"
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackH
                                gap={3}
                                principle="flex-action"
                                explain="Groups search, locale, theme, cart, account, and mobile menu triggers on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <InputButtonLike
                                                    placeholder={searchPlaceholder}
                                                    icon={MagnifyingGlassIcon}
                                                    suffix={() => <ShortcutHint shortcutLabel={shortcutLabel} />}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={MagnifyingGlassIcon}
                                                    ariaLabel={searchPlaceholder}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <StackH
                                                    gap={3}
                                                    principle="flex-action"
                                                    explain="Groups language and theme controls on one horizontal peer row so they share a single hit baseline."
                                                    items={[
                                                        () => (
                                                            <NavbarLanguageMenu
                                                                languages={languages}
                                                                activeLocale={activeLocale}
                                                                onLocaleChange={onLocaleChange}
                                                            />
                                                        ),
                                                        () => (
                                                            <NavbarThemeSwitch
                                                                isDarkMode={isDarkMode}
                                                                onThemeToggle={onThemeToggle}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HeroButton
                                            isIconOnly
                                            variant="tertiary"
                                            className="rounded-full"
                                            aria-label="Cart"
                                            onPress={onCartPress}
                                        >
                                            <Badge color="accent" count={cartCount}>
                                                <ShoppingCartIcon className="size-5" />
                                            </Badge>
                                        </HeroButton>
                                    ),
                                    ...(account.isAuthed
                                        ? [
                                            () => (
                                                <Popover isOpen={isNotificationsOpen} onOpenChange={setNotificationsOpen}>
                                                    <HeroButton
                                                        isIconOnly
                                                        variant="tertiary"
                                                        className="rounded-full"
                                                        aria-label="Notifications"
                                                    >
                                                        <Badge color="danger" count={notifications.unreadCount}>
                                                            <BellIcon className="size-5" />
                                                        </Badge>
                                                    </HeroButton>
                                                    <PopoverContent placement="bottom right" className="w-[360px]">
                                                        {/* inset-exception: vendor popover body padding, wider than tall, not a surface inset */}
                                                        <StackV
                                                            gap={2}
                                                            principle="control-pad"
                                                            explain="Control hit-area inset ΓÇö not row-pad, because this pads a single interactive control rather than a full content row."
                                                            padding={{ x: 3, y: 2 }}
                                                            items={[
                                                                () => (
                                                                    <StackH
                                                                        gap={3}
                                                                        principle="sibling-stack"
                                                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                        justify="between"
                                                                        items={[
                                                                            () => <Typography size="sm" weight="bold" text="Notifications" />,
                                                                            ...(notifications.unreadCount > 0
                                                                                ? [
                                                                                    () => (
                                                                                        <Button
                                                                                            isIconOnly
                                                                                            variant="ghost"
                                                                                            size="sm"
                                                                                            prefixIcon={ChecksIcon}
                                                                                            ariaLabel="Mark all as read"
                                                                                            onPress={notifications.onMarkAllRead}
                                                                                        />
                                                                                    ),
                                                                                ]
                                                                                : []),
                                                                        ]}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <AsyncContent
                                                                        isLoading={notifications.isLoading && notifications.items.length === 0}
                                                                        skeleton={() => (
                                                                            <StackV
                                                                                gap={1}
                                                                                principle="sibling-stack"
                                                                                explain="Same-kind peer stack of notification skeleton rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                items={[() => notificationSkeletonRows]}
                                                                            />
                                                                        )}
                                                                        isEmpty={notifications.items.length === 0}
                                                                        emptyContent={{ title: "No notifications yet" }}
                                                                        error={notifications.error}
                                                                        errorContent={{
                                                                            title: notifications.error ?? "",
                                                                            onRetry: notifications.onRetry,
                                                                            retryLabel: "Try again",
                                                                        }}
                                                                        content={() => (
                                                                            <ScrollArea
                                                                                axis="y"
                                                                                principle="flex-fill"
                                                                                explain="Owns local vertical overflow for the notification list so long threads do not grow the popover past the viewport."
                                                                                body={() => (
                                                                                    <StackV
                                                                                        gap={1}
                                                                                        principle="sibling-stack"
                                                                                        explain="Same-kind peer stack of notification rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                        items={[() => notificationRows]}
                                                                                    />
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Button
                                                                        variant="ghost"
                                                                        size="sm"
                                                                        label="See all"
                                                                        onPress={notifications.onSeeAll}
                                                                    />
                                                                ),
                                                            ]}
                                                        />
                                                    </PopoverContent>
                                                </Popover>
                                            ),
                                        ]
                                        : []),
                                    () => (
                                        <Dropdown isOpen={isAccountOpen} onOpenChange={setAccountOpen}>
                                            <HeroButton
                                                isIconOnly
                                                variant="tertiary"
                                                className="rounded-full"
                                                aria-label="Account"
                                            >
                                                {account.isAuthed ? (
                                                    <Avatar
                                                        size="sm"
                                                        name={account.user?.username}
                                                        src={account.user?.avatarUrl ?? undefined}
                                                        seed={account.user?.email ?? account.user?.username}
                                                    />
                                                ) : (
                                                    <UserIcon className="size-5" />
                                                )}
                                            </HeroButton>
                                            <Dropdown.Popover placement="bottom right" className="w-[300px]">
                                                <StackV
                                                    gap={1}
                                                    padding={4}
                                                    principle="cell-pad"
                                                    explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                                    body={() => accountMenuHeader}
                                                />
                                                <Divider />
                                                <Dropdown.Menu aria-label="Account">
                                                    <Dropdown.Section>
                                                        {account.menuItems.map((item) => {
                                                            const Icon = item.icon
                                                            return (
                                                                <Dropdown.Item
                                                                    key={item.id}
                                                                    id={item.id}
                                                                    textValue={item.label}
                                                                    className={item.isDanger ? "text-danger-soft-foreground" : undefined}
                                                                    onPress={item.onPress}
                                                                >
                                                                    {Icon ? <Icon className="size-5" /> : null}
                                                                    <Label className={item.isDanger ? "text-danger-soft-foreground" : undefined}>{item.label}</Label>
                                                                </Dropdown.Item>
                                                            )
                                                        })}
                                                    </Dropdown.Section>
                                                </Dropdown.Menu>
                                            </Dropdown.Popover>
                                        </Dropdown>
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={SidebarSimpleIcon}
                                                    ariaLabel="Open mobile menu"
                                                    onPress={() => onMobileDrawerOpenChange(true)}
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            </div>

            {/* mobile navigation drawer ΓÇö the ONE local (non-overlay-store) drawer this run's
                contract calls for; every other overlay in this system opens through the global
                store (see canon Rule 13), this one is controlled straight by the caller. */}
            <DrawerShell
                isOpen={isMobileDrawerOpen}
                onOpenChange={onMobileDrawerOpenChange}
                placement="right"
                title="Mobile menu"
                body={() => (
                    <StackV
                        gap={6}
                        principle="group-boundary"
                        explain="Separates mobile route list from language/theme controls so each region keeps its own seam owner ΓÇö not sibling-stack, because these are distinct section roles rather than repeating peers."
                        items={[
                            () => (
                                <StackV
                                    gap={2}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of mobile route rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                    items={[() => mobileNavRows]}
                                />
                            ),
                            () => <Divider />,
                            () => (
                                <StackV
                                    gap={4}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of language and theme rows ΓÇö not group-boundary, because these are repeating preference peers rather than section groups."
                                    items={[
                                        () => (
                                            <StackH
                                                gap={3}
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                justify="between"
                                                items={[
                                                    () => <Typography size="sm" text="Language" />,
                                                    () => (
                                                        <NavbarLanguageMenu
                                                            languages={languages}
                                                            activeLocale={activeLocale}
                                                            onLocaleChange={onLocaleChange}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <StackH
                                                gap={3}
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                justify="between"
                                                items={[
                                                    () => <Typography size="sm" text="Theme" />,
                                                    () => (
                                                        <NavbarThemeSwitch
                                                            isDarkMode={isDarkMode}
                                                            onThemeToggle={onThemeToggle}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                        ]}
                    />
                )}
            />
        </nav>
    )
}

export { Navbar }

import React, { useEffect, useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import {
    Button as HeroButton,
    Dropdown,
    Kbd,
    Label,
    Popover,
    PopoverContent,
} from "@heroui/react"
import {
    BellIcon,
    ChecksIcon,
    CircleIcon,
    MagnifyingGlassIcon,
    ShoppingCartIcon,
    SidebarSimpleIcon,
    UserIcon,
} from "@phosphor-icons/react"
import { NavbarLanguageMenu } from "./NavbarLanguageMenu"
import { NavbarThemeSwitch } from "./NavbarThemeSwitch"
import type { NavbarLanguageOption } from "./types"
import { Logo } from "@/components/atoms/display/Logo"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Badge } from "@/components/atoms/display/Badge"
import { Divider } from "@/components/atoms/display/Divider"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Typography } from "@/components/atoms/text/Typography"
import { Button, type IconComponent } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"
import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { ListRow } from "@/components/composites/lists/List"
import { DrawerShell } from "@/components/composites/layout/DrawerShell"
import { HideAbove } from "@/components/frames/HideAbove"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { ShowFrom } from "@/components/frames/ShowFrom"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `Navbar` ΓÇö the sticky top app bar. Two structural leaves: the desktop row
 * (route pills + inline language/theme) and the mobile collapsed row (icon bar
 * + drawer trigger) are different compositions. Signed-in vs guest, empty vs
 * busy badges, and drawer open vs closed are data, so they are states inside
 * the matching leaf. Both leaves render the same component (the `@app-md:`
 * rules live in its className), so the mobile leaf pins a narrow
 * `renderClassName` frame to force the collapsed row into view.
 */

/** One top-level desktop/mobile route entry. */
export interface NavLinkItem {
    /** Stable id ΓÇö also the value reported to the desktop pill group. */
    id: string
    /** Visible label, already localized by the caller. */
    label: string
    /** Whether this entry matches the current route. */
    isActive?: boolean
    /** Fired when the entry is picked (desktop pill or mobile drawer row). */
    onPress: () => void
}

export type { NavbarLanguageOption }

/** One row in the notification popover's list. */
export interface NavbarNotificationItem {
    /** Stable id. */
    id: string
    /** Primary line, already resolved/translated by the caller. */
    title: string
    /** Optional secondary line. */
    subtitle?: string
    /** Already-formatted relative time (e.g. "3 hours ago") ΓÇö locale math is app wiring. */
    timeLabel: string
    /** `false` renders the unread dot leading the row. */
    isRead: boolean
}

/** Notification bell data + the callbacks its popover fires. */
export interface NavbarNotificationsData {
    /** Drives the bell's count badge; `0` hides it. */
    unreadCount: number
    /** Most-recent page, newest first. */
    items: Array<NavbarNotificationItem>
    /** `true` while the FIRST page is loading (no cache yet). */
    isLoading: boolean
    /** Already-translated error message; `null`/absent ΓåÆ no error branch. */
    error?: string | null
    /** Fired when a row is pressed (mark-read + navigate is the caller's job). */
    onItemPress: (item: NavbarNotificationItem) => void
    /** Fired by the header's bulk action. */
    onMarkAllRead: () => void
    /** Fired by the footer's deep-link action. */
    onSeeAll: () => void
    /** Fired by the error branch's retry button. */
    onRetry: () => void
}

/** The signed-in viewer, as far as the account menu's header row needs to know. */
export interface NavbarAccountUser {
    /** Drives the avatar fallback + the header row's primary line. */
    username: string
    /** Shown as the header row's secondary `@handle` line. */
    email?: string
    /** Uploaded avatar URL; `Avatar`'s own fallback chain covers the rest. */
    avatarUrl?: string | null
}

/** One row of the account dropdown's action list ΓÇö covers BOTH the guest rows
 * (sign in / sign up) and the authed rows (dashboard / profile / sign out); the
 * caller decides which set to hand in via {@link NavbarAccountData.isAuthed}. */
export interface NavbarAccountMenuItem {
    /** Stable id. */
    id: string
    /** Visible label, already localized. */
    label: string
    /** Leading glyph, atom-scale (`size-5`) as this block owns the icon column. */
    icon?: IconComponent
    /** `true` ΓåÆ renders in the destructive tone (e.g. "Sign out"). */
    isDanger?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Account menu data + the one state flag its header/list branch on. */
export interface NavbarAccountData {
    /** `true` ΓåÆ header shows {@link NavbarAccountData.user}; `false` ΓåÆ the guest prompt. */
    isAuthed: boolean
    /** Present only when {@link NavbarAccountData.isAuthed}. */
    user?: NavbarAccountUser
    /** `true` while the shared "who am I" query has not resolved yet. */
    isLoading: boolean
    /** The action rows below the header (see {@link NavbarAccountMenuItem}). */
    menuItems: Array<NavbarAccountMenuItem>
}

/** Props for {@link Navbar}. */
export interface NavbarProps {
    /** Fired when the brand mark is pressed ΓÇö routing "home" is the caller's call. */
    onLogoPress: () => void
    /** Route entries ΓÇö the ONE source both the desktop pills and the mobile drawer read. */
    navItems: Array<NavLinkItem>

    /** Placeholder text for the desktop search field; doubles as the mobile icon's aria-label. */
    searchPlaceholder: string
    /** Already-formatted shortcut hint (e.g. `"Ctrl K"`, `"ΓîÿK"`) ΓÇö OS detection is app wiring. */
    shortcutLabel: string
    /** Fired when the search trigger (field or icon) is pressed, or Ctrl/Cmd+K is hit. */
    onSearchPress: () => void

    /** Selectable locales. */
    languages: Array<NavbarLanguageOption>
    /** Currently active locale ΓÇö must match one entry's `code`. */
    activeLocale: string
    /** Fired with the newly picked locale code. */
    onLocaleChange: (code: string) => void

    /** Dark-mode on/off (controlled). */
    isDarkMode: boolean
    /** Fired with the new on/off state. */
    onThemeToggle: (isDark: boolean) => void

    /** Items currently in the cart; `0` hides the count badge. */
    cartCount: number
    /** Fired when the cart icon is pressed. */
    onCartPress: () => void

    /** Notification bell data + callbacks. */
    notifications: NavbarNotificationsData
    /** Account menu data + callbacks. */
    account: NavbarAccountData

    /** Whether the mobile navigation drawer is open. Controlled by the caller. */
    isMobileDrawerOpen: boolean
    /** Fired on backdrop click / Escape / the close button / a row navigating away. */
    onMobileDrawerOpenChange: (isOpen: boolean) => void
}

interface ShortcutHintProps {
    shortcutLabel: string
}
const ShortcutHint = ({ shortcutLabel }: ShortcutHintProps) => (
    <Kbd><Kbd.Content>{shortcutLabel}</Kbd.Content></Kbd>
)

/**
 * The sticky top app bar. See the file header for the full reuse ledger and the
 * judgement calls this port makes.
 *
 * @param props - {@link NavbarProps}
 */
const Navbar = ({
    onLogoPress,
    navItems,
    searchPlaceholder,
    shortcutLabel,
    onSearchPress,
    languages,
    activeLocale,
    onLocaleChange,
    isDarkMode,
    onThemeToggle,
    cartCount,
    onCartPress,
    notifications,
    account,
    isMobileDrawerOpen,
    onMobileDrawerOpenChange,
}: NavbarProps) => {
    const [isNotificationsOpen, setNotificationsOpen] = useState(false)
    const [isAccountOpen, setAccountOpen] = useState(false)

    // Ctrl/Cmd+K ΓÇö carried over from the real component (see file header): it only
    // ever calls a prop this block already owns, so it is not new app wiring.
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            const isK = event.key?.toLowerCase() === "k"
            if (!isK || !(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            onSearchPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [onSearchPress])

    const activeNavId = navItems.find((item) => item.isActive)?.id ?? ""

    const notificationSkeletonRows = [0, 1, 2].map((row) => (
        <ListRow key={row} title="" isSkeleton />
    ))

    const notificationRows = notifications.items.map((item, index) => (
        <ListRow
            key={item.id}
            leading={!item.isRead ? (
                ({ isSkeleton }: SkeletonProps) =>
                    isSkeleton ? null : <CircleIcon weight="fill" aria-hidden focusable="false" className="size-2 text-accent-soft-foreground" />
            ) : undefined}
            title={item.title}
            subtitle={item.subtitle}
            meta={() => <Typography size="xs" color="muted" text={item.timeLabel} />}
            onPress={() => notifications.onItemPress(item)}
            divider={index < notifications.items.length - 1}
        />
    ))

    const accountMenuHeader = (
        <AsyncContent
            isLoading={account.isLoading}
            skeleton={() => <UserCell username="" isSkeleton />}
            content={() => (account.isAuthed && account.user ? (
                <UserCell
                    username={account.user.username}
                    avatar={account.user.avatarUrl}
                    handle={account.user.email}
                />
            ) : (
                <StackH
                    gap={3}
                    principle="icon-text"
                    explain="Avatar beside its guest prompt ΓÇö not name-handle, because this pairs a glyph with instructional text rather than a name/handle identity."
                    items={[
                        () => <Avatar icon={UserIcon} fallback="icon" />,
                        () => <Typography size="sm" color="muted" text="Sign in to save your learning progress" />,
                    ]}
                />
            ))}
        />
    )

    const mobileNavRows = navItems.map((item) => (
        <Button
            key={item.id}
            variant={item.isActive ? "secondary" : "ghost"}
            align="start"
            label={item.label}
            onPress={() => {
                item.onPress()
                onMobileDrawerOpenChange(false)
            }}
        />
    ))

    return (
        <nav className="sticky top-0 z-50 border-b border-default bg-surface">
            {/* primary row ΓÇö fixed 4rem tall, matching the real bar's height contract */}
            <div className="h-16 min-h-16">
                <StackH
                    gap={6}
                    principle="block-boundary"
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    justify="between"
                    padding={{ x: 4 }}
                    items={[
                        () => (
                            <StackH
                                gap={6}
                                principle="flex-action"
                                explain="Groups brand mark and desktop route pills on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <span
                                            role="button"
                                            tabIndex={0}
                                            aria-label="StarCi Academy"
                                            onClick={onLogoPress}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter" || event.key === " ") onLogoPress()
                                            }}
                                            className="inline-flex cursor-pointer"
                                        >
                                            <Logo />
                                        </span>
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <ButtonRadioGroup
                                                    items={navItems.map((item) => ({
                                                        value: item.id,
                                                        content: <Typography size="sm" text={item.label} />,
                                                    }))}
                                                    value={activeNavId}
                                                    onChange={(id) => navItems.find((item) => item.id === id)?.onPress()}
                                                    ariaLabel="Main navigation"
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackH
                                gap={3}
                                principle="flex-action"
                                explain="Groups search, locale, theme, cart, account, and mobile menu triggers on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <InputButtonLike
                                                    placeholder={searchPlaceholder}
                                                    icon={MagnifyingGlassIcon}
                                                    suffix={() => <ShortcutHint shortcutLabel={shortcutLabel} />}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={MagnifyingGlassIcon}
                                                    ariaLabel={searchPlaceholder}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <StackH
                                                    gap={3}
                                                    principle="flex-action"
                                                    explain="Groups language and theme controls on one horizontal peer row so they share a single hit baseline."
                                                    items={[
                                                        () => (
                                                            <NavbarLanguageMenu
                                                                languages={languages}
                                                                activeLocale={activeLocale}
                                                                onLocaleChange={onLocaleChange}
                                                            />
                                                        ),
                                                        () => (
                                                            <NavbarThemeSwitch
                                                                isDarkMode={isDarkMode}
                                                                onThemeToggle={onThemeToggle}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HeroButton
                                            isIconOnly
                                            variant="tertiary"
                                            className="rounded-full"
                                            aria-label="Cart"
                                            onPress={onCartPress}
                                        >
                                            <Badge color="accent" count={cartCount}>
                                                <ShoppingCartIcon className="size-5" />
                                            </Badge>
                                        </HeroButton>
                                    ),
                                    ...(account.isAuthed
                                        ? [
                                            () => (
                                                <Popover isOpen={isNotificationsOpen} onOpenChange={setNotificationsOpen}>
                                                    <HeroButton
                                                        isIconOnly
                                                        variant="tertiary"
                                                        className="rounded-full"
                                                        aria-label="Notifications"
                                                    >
                                                        <Badge color="danger" count={notifications.unreadCount}>
                                                            <BellIcon className="size-5" />
                                                        </Badge>
                                                    </HeroButton>
                                                    <PopoverContent placement="bottom right" className="w-[360px]">
                                                        {/* inset-exception: vendor popover body padding, wider than tall, not a surface inset */}
                                                        <StackV
                                                            gap={2}
                                                            principle="control-pad"
                                                            explain="Control hit-area inset ΓÇö not row-pad, because this pads a single interactive control rather than a full content row."
                                                            padding={{ x: 3, y: 2 }}
                                                            items={[
                                                                () => (
                                                                    <StackH
                                                                        gap={3}
                                                                        principle="sibling-stack"
                                                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                        justify="between"
                                                                        items={[
                                                                            () => <Typography size="sm" weight="bold" text="Notifications" />,
                                                                            ...(notifications.unreadCount > 0
                                                                                ? [
                                                                                    () => (
                                                                                        <Button
                                                                                            isIconOnly
                                                                                            variant="ghost"
                                                                                            size="sm"
                                                                                            prefixIcon={ChecksIcon}
                                                                                            ariaLabel="Mark all as read"
                                                                                            onPress={notifications.onMarkAllRead}
                                                                                        />
                                                                                    ),
                                                                                ]
                                                                                : []),
                                                                        ]}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <AsyncContent
                                                                        isLoading={notifications.isLoading && notifications.items.length === 0}
                                                                        skeleton={() => (
                                                                            <StackV
                                                                                gap={1}
                                                                                principle="sibling-stack"
                                                                                explain="Same-kind peer stack of notification skeleton rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                items={[() => notificationSkeletonRows]}
                                                                            />
                                                                        )}
                                                                        isEmpty={notifications.items.length === 0}
                                                                        emptyContent={{ title: "No notifications yet" }}
                                                                        error={notifications.error}
                                                                        errorContent={{
                                                                            title: notifications.error ?? "",
                                                                            onRetry: notifications.onRetry,
                                                                            retryLabel: "Try again",
                                                                        }}
                                                                        content={() => (
                                                                            <ScrollArea
                                                                                axis="y"
                                                                                principle="flex-fill"
                                                                                explain="Owns local vertical overflow for the notification list so long threads do not grow the popover past the viewport."
                                                                                body={() => (
                                                                                    <StackV
                                                                                        gap={1}
                                                                                        principle="sibling-stack"
                                                                                        explain="Same-kind peer stack of notification rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                        items={[() => notificationRows]}
                                                                                    />
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Button
                                                                        variant="ghost"
                                                                        size="sm"
                                                                        label="See all"
                                                                        onPress={notifications.onSeeAll}
                                                                    />
                                                                ),
                                                            ]}
                                                        />
                                                    </PopoverContent>
                                                </Popover>
                                            ),
                                        ]
                                        : []),
                                    () => (
                                        <Dropdown isOpen={isAccountOpen} onOpenChange={setAccountOpen}>
                                            <HeroButton
                                                isIconOnly
                                                variant="tertiary"
                                                className="rounded-full"
                                                aria-label="Account"
                                            >
                                                {account.isAuthed ? (
                                                    <Avatar
                                                        size="sm"
                                                        name={account.user?.username}
                                                        src={account.user?.avatarUrl ?? undefined}
                                                        seed={account.user?.email ?? account.user?.username}
                                                    />
                                                ) : (
                                                    <UserIcon className="size-5" />
                                                )}
                                            </HeroButton>
                                            <Dropdown.Popover placement="bottom right" className="w-[300px]">
                                                <StackV
                                                    gap={1}
                                                    padding={4}
                                                    principle="cell-pad"
                                                    explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                                    body={() => accountMenuHeader}
                                                />
                                                <Divider />
                                                <Dropdown.Menu aria-label="Account">
                                                    <Dropdown.Section>
                                                        {account.menuItems.map((item) => {
                                                            const Icon = item.icon
                                                            return (
                                                                <Dropdown.Item
                                                                    key={item.id}
                                                                    id={item.id}
                                                                    textValue={item.label}
                                                                    className={item.isDanger ? "text-danger-soft-foreground" : undefined}
                                                                    onPress={item.onPress}
                                                                >
                                                                    {Icon ? <Icon className="size-5" /> : null}
                                                                    <Label className={item.isDanger ? "text-danger-soft-foreground" : undefined}>{item.label}</Label>
                                                                </Dropdown.Item>
                                                            )
                                                        })}
                                                    </Dropdown.Section>
                                                </Dropdown.Menu>
                                            </Dropdown.Popover>
                                        </Dropdown>
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={SidebarSimpleIcon}
                                                    ariaLabel="Open mobile menu"
                                                    onPress={() => onMobileDrawerOpenChange(true)}
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            </div>

            {/* mobile navigation drawer ΓÇö the ONE local (non-overlay-store) drawer this run's
                contract calls for; every other overlay in this system opens through the global
                store (see canon Rule 13), this one is controlled straight by the caller. */}
            <DrawerShell
                isOpen={isMobileDrawerOpen}
                onOpenChange={onMobileDrawerOpenChange}
                placement="right"
                title="Mobile menu"
                body={() => (
                    <StackV
                        gap={6}
                        principle="group-boundary"
                        explain="Separates mobile route list from language/theme controls so each region keeps its own seam owner ΓÇö not sibling-stack, because these are distinct section roles rather than repeating peers."
                        items={[
                            () => (
                                <StackV
                                    gap={2}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of mobile route rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                    items={[() => mobileNavRows]}
                                />
                            ),
                            () => <Divider />,
                            () => (
                                <StackV
                                    gap={4}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of language and theme rows ΓÇö not group-boundary, because these are repeating preference peers rather than section groups."
                                    items={[
                                        () => (
                                            <StackH
                                                gap={3}
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                justify="between"
                                                items={[
                                                    () => <Typography size="sm" text="Language" />,
                                                    () => (
                                                        <NavbarLanguageMenu
                                                            languages={languages}
                                                            activeLocale={activeLocale}
                                                            onLocaleChange={onLocaleChange}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <StackH
                                                gap={3}
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                justify="between"
                                                items={[
                                                    () => <Typography size="sm" text="Theme" />,
                                                    () => (
                                                        <NavbarThemeSwitch
                                                            isDarkMode={isDarkMode}
                                                            onThemeToggle={onThemeToggle}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                        ]}
                    />
                )}
            />
        </nav>
    )
}

export { Navbar }
